/**
 * World and schematic photography, embedded as base64 data URIs.
 *
 * These were file imports from `src/assets/world/*.jpg`. Binary files are the
 * one thing that silently breaks a single-file build: any environment that
 * restores source without the images (a fresh clone that ignores them, a CI
 * cache miss, this sandbox) fails to resolve the import and the whole console
 * white-screens. The rest of the art in this repo is already embedded for
 * exactly this reason (assets/embedded/brand.ts, blocks.ts) — this brings the
 * world imagery in line with that rule.
 *
 * Source: chobesujal24/dash-new public/assets/world + aistudio renders,
 * re-encoded at 1040px / q60–64 (446 KB total).
 * Regenerate with `node scripts/embed-world.mjs` (see that file for the recipe).
 */

const heroBanner = "data:image/jpeg;base64,";

const lanternPier = "data:image/jpeg;base64,";

const moonlitBridge = "data:image/jpeg;base64,";

const cliffsidePagoda = "data:image/jpeg;base64,";

const clusterDepot = "data:image/jpeg;base64,";

const perimeterGuard = "data:image/jpeg;base64,";

const netherGrind = "data:image/jpeg;base64,";

